MW.advancedJobs={warrior:{name:'검성',skill:'천광 회전참',hp:120,atk:12,def:9,multiplier:3.8,detail:'전사 → 검성 · 생명 +80 / 공격 +12 / 방어 +6 · 천광 회전참'},archer:{name:'신궁',skill:'유성 삼연사',hp:20,atk:17,def:2,multiplier:3.6,detail:'궁수 → 신궁 · 생명 +20 / 공격 +14 / 방어 +2 · 활 사거리 +30 · 유성 삼연사'},mage:{name:'대마도사',skill:'천체 붕괴',hp:20,atk:24,def:1,multiplier:4,detail:'마법사 → 대마도사 · 생명 +20 / 공격 +18 / 방어 +1 · 지팡이 사거리 +30 · 천체 붕괴'}};
MW.jobInfo=p=>p.promotions?.includes(p.job)?MW.advancedJobs[p.job]:MW.jobs[p.job]||MW.jobs.traveler;
(()=>{const R=MW.Renderer.prototype,base=R.player;R.player=function(p,face=0,frame=0){const sprite=base.call(this,p,face,frame);if(!p.promotions?.includes(p.job))return sprite;return this.art('advanced:'+p.job+':'+p.equip.weapon+':'+p.equip.armor+':'+face+':'+frame,80,90,c=>{c.drawImage(sprite,0,0);if(face===3){c.translate(80,0);c.scale(-1,1);}const rect=(x,y,w,h,col)=>this.rect(c,x,y,w,h,col),gold='#ead392',light='#fff0bf';if(p.job==='warrior'){rect(39,18,4,11,'#c88675');rect(40,17,2,10,light);rect(30,32,22,2,gold);rect(27,52,8,2,gold);rect(49,52,8,2,gold);rect(40,55,3,8,gold);}if(p.job==='archer'){rect(49,22,3,13,gold);rect(52,22,3,8,light);rect(31,35,20,2,gold);rect(32,55,3,12,gold);rect(50,55,3,12,gold);}if(p.job==='mage'){rect(26,37,31,2,gold);rect(40,29,3,5,light);rect(36,31,11,1,gold);rect(33,77,19,2,gold);rect(41,56,2,9,light);rect(37,59,10,2,gold);}});};const baseEffect=R.combatEffect;R.combatEffect=function(game){baseEffect.call(this,game);if(!game.strike?.promoted||game.strike.kind!=='skill')return;const c=this.ctx,t=1-game.slash/.45;c.save();c.globalAlpha=Math.min(1,(1-t)*3);for(let i=0;i<8;i++){const a=i*Math.PI/4+t,r=30+t*65,x=game.strike.x+Math.cos(a)*r,y=game.strike.y-15+Math.sin(a)*r;this.rect(c,x-3,y,7,1,'#f5dda0');this.rect(c,x,y-3,1,7,'#fff4cc');}c.restore();};})();
MW.installProgression=function(Game){const P=Game.prototype,load=P.load,change=P.changeJob,jobMenu=P.jobMenu,inventory=P.inventory,shop=P.shop;
P.ensureProgression=function(){this.p.promotions??=[];this.p.starterClaims??=['warrior','archer','mage'].filter(id=>this.p.owned.includes(id+'armor1')||this.p.job===id);this.p.guideSeen??=[];};
P.load=function(){load.call(this);this.ensureProgression();};
P.changeJob=function(id){this.ensureProgression();if(!['warrior','archer','mage'].includes(id)||this.p.level<3||this.dungeon||this.tower||this.p.x>=22*48)return;if(!this.p.starterClaims.includes(id)){this.p.starterClaims.push(id);change.call(this,id);return;}this.p.job=id;for(const type of ['weapon','armor']){const owned=MW.items.filter(i=>i.type===type&&this.p.owned.includes(i.id)&&(!i.job||i.job===id)).sort((a,b)=>(b.tier||0)-(a.tier||0)||Number(b.job===id)-Number(a.job===id));this.p.equip[type]=owned[0]?.id||null;}this.p.hp=this.stats().hp;this.p.mp=100;this.cool={attack:0,skill:0,dash:0};this.slash=0;this.save();this.ui();this.notify(MW.jobInfo(this.p).name+'의 길 · 보유 장비 장착');this.jobMenu();};
P.jobMenu=function(){this.ensureProgression();jobMenu.call(this);const box=$('#dialogtext').children[0];box.append(this.card('2차 전직 · 레벨 10','1차 직업을 선택한 뒤 마을에서 승급할 수 있습니다. 직업별 승급 기록은 저장되며, 다른 직업을 선택했다 돌아와도 유지됩니다. 수련 장비는 직업마다 한 번만 지급됩니다.'));for(const id of ['warrior','archer','mage']){const info=MW.advancedJobs[id],done=this.p.promotions.includes(id),c=this.card(info.name,info.detail);this.preview(c,{job:id,promotions:[id],equip:{weapon:id==='warrior'?'weapon1':id+'weapon1',armor:id+'armor1'}});this.button(c,done?'승급 완료':this.p.job!==id?MW.jobs[id].name+' 선택 필요':this.p.level<10?'레벨 10 필요':'2차 전직',()=>{if(done||this.p.job!==id||this.p.level<10){this.show('2차 전직',info.name,done?'이미 승급한 직업입니다.':this.p.job!==id?MW.jobs[id].name+'로 먼저 1차 전직하세요.':'레벨 10부터 2차 전직할 수 있습니다.',[['직업 목록',()=>this.jobMenu()]]);return;}if(this.dungeon||this.tower||this.p.x>=22*48){this.show('2차 전직','마을에서 승급','마을로 돌아온 뒤 사범 또는 캐릭터 메뉴에서 승급하세요.',[['직업 목록',()=>this.jobMenu()]]);return;}this.show('2차 전직',info.name+'의 길',info.detail+'\n현재 장비는 유지하며, 능력치와 기술·외형이 강화됩니다.',[['승급 확정',()=>this.promote(id)],['돌아가기',()=>this.jobMenu()]]);});box.append(c);}};
P.promote=function(id){this.ensureProgression();if(id!==this.p.job||!MW.advancedJobs[id]||this.p.level<10||this.p.promotions.includes(id)||this.dungeon||this.tower||this.p.x>=22*48)return false;this.p.promotions.push(id);this.p.hp=this.stats().hp;this.p.mp=100;this.cool={attack:0,skill:0,dash:0};this.p.log.push(MW.advancedJobs[id].name+'로 2차 전직했습니다.');this.save();this.ui();this.notify(MW.advancedJobs[id].name+' 승급 완료');this.jobMenu();return true;};
P.inventory=function(){inventory.call(this);this.button($('#choices'),'아이템 판매 / 분해',()=>this.itemManage());};
P.shop=function(n){shop.call(this,n);this.button($('#choices'),'보유 아이템 판매 / 분해',()=>this.itemManage());};
P.itemQuote=function(id,mode,quantity=1){const item=MW.items.find(i=>i.id===id);if(!item||!['sell','salvage'].includes(mode)||!Number.isInteger(quantity)||quantity<1)return null;const use=item.type==='use',count=use?this.p.bag[id]||0:this.p.owned.filter(v=>v===id).length;if(quantity>count||(!use&&quantity!==1)||Object.values(this.p.equip).includes(id))return null;if(mode==='salvage'&&use)return null;return{item,quantity,gold:mode==='sell'?Math.max(1,Math.floor(item.price*.4))*quantity:0,ore:mode==='salvage'?Math.max(1,(item.tier||1)*2)*quantity:0};};
P.disposeItem=function(id,mode,quantity=1){const q=this.itemQuote(id,mode,quantity);if(!q)return false;if(q.item.type==='use')this.p.bag[id]-=quantity;else this.p.owned=this.p.owned.filter(v=>v!==id);this.p.gold+=q.gold;this.p.bag.ore+=q.ore;this.save();this.ui();this.notify(q.item.name+' '+quantity+'개 '+(mode==='sell'?'판매 · '+q.gold+'냥':'분해 · 강화석 '+q.ore));return true;};
P.confirmDisposal=function(id,mode,quantity){const q=this.itemQuote(id,mode,quantity);if(!q)return;this.show('아이템 정리',mode==='sell'?'판매 확인':'분해 확인',q.item.name+' '+quantity+'개를 '+(mode==='sell'?'판매':'분해')+'합니다.\n보상: '+(q.gold?q.gold+'냥':'강화석 '+q.ore)+'\n아이템은 가방에서 제거됩니다.',[['확정',()=>{this.disposeItem(id,mode,quantity);this.itemManage();}],['취소',()=>this.itemManage()]]);};
P.itemManage=function(){this.stopAuto();const box=this.content();box.append(this.card('보유 아이템 정리','판매: 구입가의 40% · 장비 분해: 등급 × 강화석 2개. 장착 중인 장비는 먼저 해제하세요. 포션·보급식·부적은 판매할 수 있습니다.'));let count=0;for(const item of MW.items){const use=item.type==='use',quantity=use?this.p.bag[item.id]||0:this.p.owned.includes(item.id)?1:0;if(!quantity)continue;count++;const equipped=Object.values(this.p.equip).includes(item.id),c=this.card(item.name+(equipped?' · 장착 중':''),quantity+'개 · 판매가 '+Math.max(1,Math.floor(item.price*.4))+'냥 / 개'+(!use?' · 분해: 강화석 '+(item.tier||1)*2:''));if(equipped)c.append(this.card('장착 해제 필요','가방에서 장착을 해제한 뒤 판매·분해할 수 있습니다.'));else{this.button(c,'1개 판매',()=>this.confirmDisposal(item.id,'sell',1));if(use&&quantity>1){this.button(c,Math.min(5,quantity)+'개 판매',()=>this.confirmDisposal(item.id,'sell',Math.min(5,quantity)));if(quantity>5)this.button(c,'전부 판매 ('+quantity+')',()=>this.confirmDisposal(item.id,'sell',quantity));}if(!use)this.button(c,'분해',()=>this.confirmDisposal(item.id,'salvage',1));}box.append(c);}if(!count)box.append(this.card('정리할 아이템 없음','상점에서 구입하거나 탐험으로 장비와 보급품을 얻으세요.'));this.show('가방 정리','판매 / 분해 · '+this.p.gold+'냥',box,[['장비 / 가방',()=>this.inventory()]]);};
P.guideContext=function(){if(this.p.level>=10&&this.p.job!=='traveler'&&!this.p.promotions?.includes(this.p.job)&&!this.p.guideSeen?.includes('promotion:'+this.p.job))return{key:'promotion:'+this.p.job,title:'2차 전직이 열렸어요',text:'레벨 10 달성! 마을에서 '+MW.advancedJobs[this.p.job].name+'로 승급해 능력치와 기술을 강화하세요.',label:'전직 화면 열기',action:'job'};if(this.p.level>=3&&this.p.job==='traveler'&&!this.p.guideSeen?.includes('firstjob'))return{key:'firstjob',title:'직업을 선택해 보세요',text:'레벨 3부터 전사·궁수·마법사로 전직할 수 있습니다. 마을에서 선택하면 수련 장비를 받습니다.',label:'전직 화면 열기',action:'job'};if(this.dungeon||this.tower)return{key:'expedition-guide',title:'원정과 시련',text:'퀘스트 창을 누르면 자동 전투합니다. 미궁은 적을 물리치고 세 봉인을 조사하세요. 미니맵에서 전체 지도를 열 수 있습니다.',label:'자동 진행 시작',action:'auto'};const kind=this.step()?.kind||'done',tips={talk:['여정의 시작','퀘스트 창을 누르면 안내자에게 자동 이동합니다. 도착한 대화 화면에서 여정을 시작하세요.'],scout:['금색 목표를 찾아가세요','퀘스트 창을 누르면 조사 지점으로 자동 이동합니다. 기록을 읽고 닫으면 다음 지점으로 이어집니다.'],kill:['사냥 의뢰 진행','퀘스트 창을 누르면 몬스터를 찾아 자동 사냥합니다. 체력이 낮으면 보유 회복약을 사용합니다. 직접 조작하면 자동 진행이 멈춥니다.'],collect:['흩어진 기억 수집','퀘스트 창을 눌러 기억 조각을 자동 수집하세요. 미니맵을 누르면 내 위치와 다음 목표를 볼 수 있습니다.'],puzzle:['비문의 순서를 확인하세요','자동 이동으로 제단에 도착한 뒤 비문에 적힌 순서대로 해·별·달을 선택하세요.'],escort:['순례자를 마을로','야영지에서 함께 돌아가기를 선택한 뒤 퀘스트 창을 누르세요. 순례자가 따라올 때까지 기다리며 적과 전투합니다.'],defend:['봉화를 지켜주세요','퀘스트 창을 누르면 봉화로 이동해 방어 전투를 시작합니다. 자동 전투 중에도 물약을 충분히 준비하세요.'],boss:['수호자와의 전투','가방에서 장비를 확인하고 회복약을 준비하세요. 붉은 공격 예고는 직접 이동해 피할 수 있습니다.'],return:['달 조각을 돌려주세요','안내자에게 돌아가 대화에서 달 조각을 나누면 다음 지역이 열립니다.'],done:['다음 여정을 준비하세요','월드맵에서 열린 지역으로 이동하거나 주민 의뢰·미궁·시련의 탑에 도전하세요. 안 쓰는 아이템은 가방에서 판매·분해할 수 있습니다.']},tip=tips[kind]||tips.talk;return{key:'quest:'+kind,title:tip[0],text:tip[1],label:kind==='done'?'월드맵 열기':'자동 진행 시작',action:kind==='done'?'world':'auto'};};
P.closeGuide=function(){if(this.currentGuide&&!this.p.guideSeen.includes(this.currentGuide.key)){this.p.guideSeen.push(this.currentGuide.key);this.save();}$('#guide-tooltip').hidden=true;};
P.openGuide=function(){this.ensureProgression();const tip=this.guideContext();this.currentGuide=tip;$('#guide-title').textContent=tip.title;$('#guide-text').textContent=tip.text;$('#guide-action').textContent=tip.label;$('#guide-tooltip').hidden=false;};
P.guideUI=function(){this.ensureProgression();const tip=this.guideContext();if(dialog.open||$('#regionmap').open){$('#guide-tooltip').hidden=true;return;}if(this.currentGuide&&this.currentGuide.key!==tip.key)$('#guide-tooltip').hidden=true;if(!this.p.guideSeen.includes(tip.key)&&!this.auto&&!this.paused)this.openGuide();};
const bind=P.bind;P.bind=function(){bind.call(this);$('#guide-toggle').onclick=e=>{e.stopPropagation();if($('#guide-tooltip').hidden)this.openGuide();else this.closeGuide();};$('#guide-toggle').addEventListener('keydown',e=>e.stopPropagation());$('#guide-close').onclick=()=>this.closeGuide();$('#guide-action').onclick=()=>{const tip=this.currentGuide;this.closeGuide();if(tip.action==='job')this.jobMenu();else if(tip.action==='world')this.worldMap();else if(!this.auto)this.toggleAuto();};};
};
